"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7813],{70739:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"JumpDriveGuiController","desc":"Drives both jump-drive GUI surfaces from the single `JumpStateSync` payload,\\nso the two can never disagree:\\n\\n- **Jump Drive panel** \u2014 opened by the bench ProximityPrompt. Shows the charge\\n  gauge, the destination, a Jump button, and the full named vote roster.\\n- **Vote banner** \u2014 pushed to every player the moment a vote opens, wherever\\n  they are on the train. Non-modal and must never capture input: abstaining is\\n  neutral in the resolution rule, so a vote nobody sees is a vote that always\\n  passes on the initiator\'s lone yes.\\n\\nBoth countdowns are extrapolated from the server\'s `phaseEndsAt` rather than\\ncounted down locally, so a late joiner and a player present the whole time see\\nthe same number.","realm":["Client"],"source":{"line":22,"path":"src/StarterPlayer/StarterPlayerScripts/JumpDriveGuiController.client.luau"}}')}}]);